                    && let Expression::Identifier(id) = &member.object
                    && matches!(
                        self.instance_classes
                            .get(id.name.as_str())
                            .map(String::as_str),
                        Some("MessageChannel")
                    )
                {
                    return "MessagePort.message".to_string();
                }

