//! Where a tainted value lands: assignment sinks (`innerHTML =`), method
//! sinks (`el.insertAdjacentHTML(…)`), and the call forms that reach one
//! indirectly through a summary, a wrapper, or `Reflect`.

use super::*;

impl<'a> DomXssVisitor<'a> {
    /// Walk through an assignment expression
    pub(super) fn walk_assignment_expression(&mut self, assign: &AssignmentExpression<'a>) {
        if matches!(assign.left, AssignmentTarget::AssignmentTargetIdentifier(_)) {
            self.note_webpack_alias_escape(&assign.right);
        }
        self.note_webpack_assignment(&assign.left);
        self.note_webpack_runtime(assign);
        // The property written decides which sanitizers count (see `SinkCtx`).
        let sink = match &assign.left {
            AssignmentTarget::StaticMemberExpression(member) => {
                match self.get_member_string(member) {
                    Some(path) if is_location_object_path(&path) => "location.href".to_string(),
                    _ => member.property.name.to_string(),
                }
            }
            AssignmentTarget::ComputedMemberExpression(member) => self
                .get_computed_property_string(member)
                .unwrap_or_default(),
            AssignmentTarget::AssignmentTargetIdentifier(id) if id.name == "location" => {
                "location.href".to_string()
            }
            _ => String::new(),
        };
        let (right_tainted, right_source) = self.for_sink(&sink, |v| {
            let tainted = v.is_tainted(&assign.right);
            (
                tainted,
                tainted
                    .then(|| v.find_source_in_expr(&assign.right))
                    .flatten(),
            )
        });

        // An assignment over a numeric built-in shadows it like a
        // `function parseInt(){}` declaration does.
        let assigned_name = match &assign.left {
            AssignmentTarget::StaticMemberExpression(member) => self.get_member_string(member),
            AssignmentTarget::AssignmentTargetIdentifier(id) => Some(id.name.to_string()),
            _ => None,
        };
        // A polyfill that assigns a built-in back (`Number.parseInt =
        // window.parseInt`, `window.parseInt = window.parseInt || …`) keeps it.
        if let Some(name) = assigned_name {
            let name = strip_global_object(&name);
            if NUMERIC_COERCIONS.contains(&name) && !self.is_builtin_coercion(&assign.right) {
                self.overridden_coercions.insert(name.to_string());
            }
        }

        // Assigning the `Location` object itself (`location = url`,
        // `window.location = url`) navigates exactly like `location.href = url`.
        let assigns_location = match &assign.left {
            AssignmentTarget::StaticMemberExpression(member) => self
                .get_member_string(member)
                .is_some_and(|path| is_location_object_path(&path)),
            AssignmentTarget::AssignmentTargetIdentifier(id) => {
                id.name == "location" && !self.local_names.contains("location")
