//! AST/DOM analysis orchestration + external-JS fetch.
//!
//! Extracted from the scanning hub; see `mod.rs` for the pipeline overview.

use super::*;
use std::collections::HashMap;

/// Maximum number of distinct same-origin external JS files fetched per target page fetch.
pub(crate) const MAX_EXTERNAL_JS_FILES: usize = 16;
/// Maximum bytes read from a single external JS file (matches analyzer limit).
pub(crate) const MAX_EXTERNAL_JS_BYTES: usize = 512 * 1024;
/// Ceiling on distinct light-verify GETs per `run_ast_dom_analysis` call (one
/// call per parameter). The page chooses how many sinks it carries, so without
/// a bound a 512 KiB script costs ~19k sequential requests per parameter.
/// Findings past it are still reported, just unverified.
const MAX_AST_LIGHT_VERIFY: usize = 32;
/// Ceiling on findings per call that keep a response copy (<= 64 KiB each).
const MAX_AST_EVIDENCE_BODIES: usize = 64;
/// Ceiling on parameter-carrying `<script src>` fetches per call (one call
/// per parameter).
const MAX_REFLECTED_SCRIPTS: usize = 4;

/// Run AST-based DOM XSS static analysis on the given response HTML.
///
/// `injected` is the value `param` carried in the request that produced
/// `response_text`; it lets the analyzer recognise the page's own copy of it
/// (see `PageMarkup::sent_value`).
///
/// Extracts JavaScript blocks, analyses each for DOM XSS flows, performs
/// lightweight runtime verification, and returns any findings.  De-duplicates
/// against `ast_seen` (shared across calls for the same parameter).
#[allow(clippy::too_many_arguments)]
pub(crate) async fn run_ast_dom_analysis(
    client: &reqwest::Client,
    target: &Target,
    param: &Param,
    response_text: &str,
    injected: &str,
    xml_response: bool,
    ast_seen: &mut HashSet<String>,
    cancel: Option<&std::sync::atomic::AtomicBool>,
    scan_args: &ScanArgs,
) -> Vec<crate::scanning::result::Result> {
    let mut results = Vec::new();
    // Light-verify outcome per distinct payload: the request depends only on
    // (target, param, payload), so N sinks sharing a payload cost one GET.
    // The cached body is already bounded.
    type LightVerdict = (bool, Option<String>, Option<String>);
    let mut verify_cache: HashMap<String, LightVerdict> = HashMap::new();
    let mut evidence_left = MAX_AST_EVIDENCE_BODIES;
    // The response carries this request's marker in `param`, so the markup
    // slots holding it are proven reflections (see `PageMarkup`).
    let (js_blocks, script_element_ids, mut reflected_markup) = if xml_response {
        let (js_blocks, script_ids) =
            crate::scanning::ast_integration::extract_js_and_script_ids_from_xml(response_text);
        let js_blocks = js_blocks
            .into_iter()
            .map(crate::scanning::ast_integration::JsBlock::own)
            .collect();
        (js_blocks, script_ids, Default::default())
    } else {
        crate::scanning::ast_integration::extract_js_script_ids_and_reflected_markup(response_text)
    };
    // …and the slots the pre-scan probe proved, when Stage 0 was skipped.
    if let Some(probed) = &param.reflected_markup {
        reflected_markup.merge(probed);
    }
    reflected_markup.sent_value = Some(injected.to_string());
    let posture = crate::scanning::ast_integration::PageSecurityPosture::from_target(target);
    // A same-origin `<script src>` whose URL carries the parameter hands it to
    // that script as `document.currentScript.src`.
    let mut script_markup = reflected_markup.clone();
    script_markup.current_script_src = true;
    let script_markup = Arc::new(script_markup);
    // Shared across blocks: a per-block clone is O(blocks x ids).
    let (script_element_ids, reflected_markup) =
        (Arc::new(script_element_ids), Arc::new(reflected_markup));
    // A fetched script also carries its URL and the query keys holding the
    // parameter.
    type ScriptOrigin = Option<(String, HashSet<String>)>;
    let mut blocks: Vec<(
        crate::scanning::ast_integration::JsBlock,
        &Arc<_>,
        ScriptOrigin,
    )> = js_blocks
        .into_iter()
        .map(|js| (js, &reflected_markup, None))
        .collect();
    if scan_args.analyze_external_js && !xml_response {
        for url in reflected_script_srcs(response_text, &target.url, injected) {
            if cancel.is_some_and(|c| c.load(std::sync::atomic::Ordering::Relaxed)) {
                break;
            }
            let url_str = url.as_str().to_owned();
            if !scan_args.url_in_scope(&url_str) {
                continue;
            }
            let keys = url
                .query_pairs()
                .filter(|(_, value)| carries_param(value, injected))
                .map(|(key, _)| key.into_owned())
                .collect();
            if let Some(ExternalJs::Body(body)) =
                fetch_external_js(client, target, url, scan_args).await
            {
                // Not in document order with the inline blocks: it starts
                // from no carried globals and hands none on.
                let block = crate::scanning::ast_integration::JsBlock::own(body);
                blocks.push((block, &script_markup, Some((url_str, keys))));
            }
        }
    }
    // The response's classic scripts share one global scope, in this order.
    let mut page_globals = crate::scanning::ast_dom_analysis::CarriedGlobals::new();
    for (block, markup, script_url) in blocks {
        let mut own_globals = Default::default();
        let globals = if script_url.is_some() {
            &mut own_globals
        } else {
            match block.globals(&mut page_globals, &mut own_globals) {
                Some(globals) => globals,
                None => continue,
            }
        };
        let repeat = block.is_repeat();
        let js_code = block.code;
        let findings =
            crate::scanning::ast_integration::analyze_javascript_for_dom_xss_with_html_context(
                &js_code,
                &script_element_ids,
                markup,
                posture.trusted_types_enforced,
                globals,
            );
        if repeat {
            continue;
        }
        // Normalized once per block (not per finding), and only once a
        // finding survives the dedup below — the bootstrap check is pure, so
        // running it after the `ast_seen` skip changes nothing but the cost.
        let mut normalized_js: Option<String> = None;
        for (vuln, payload, description) in findings {
            // From a fetched script, only what the parameter feeds through
            // `currentScript.src` (and, for `.get(key)`, a key that holds it):
            // its other flows belong to the page-level external-JS pass.
            if let Some((_, keys)) = &script_url {
                let Some(rest) = vuln
                    .source
                    .strip_prefix("markup:document.currentScript.src")
                else {
                    continue;
                };
                if let Some(key) = rest.strip_prefix(".get(").and_then(|r| r.split(')').next())
                    && !keys.contains(key)
                {
                    continue;
                }
            }
            let ast_key = format!(
                "{}|{}|{}|{}|{}",
                param.name, vuln.line, vuln.column, vuln.source, vuln.sink
            );
            if ast_seen.contains(&ast_key) {
                continue;
            }
            ast_seen.insert(ast_key);
            let normalized_js = normalized_js.get_or_insert_with(|| {
                crate::scanning::ast_integration::normalize_js_for_pattern_matching(&js_code)
            });
            let self_bootstrap_verified =
                crate::scanning::ast_integration::has_self_bootstrap_verification_normalized(
                    normalized_js,
                    &vuln.source,
                );
            let source_uses_url_surface = ast_source_uses_browser_url_surface(&vuln.source);
            // As-sent payload (pre-encoding applied) so the PoC URL reproduces
            // the finding, like the reflection / DOM phases. Raw for URL-surface
            // sources, which ride in the fragment / query / path of the page.
            let wire_payload = crate::encoding::pre_encoding::apply_param_encoding(&payload, param);
            let result_url = if source_uses_url_surface {
                crate::scanning::ast_integration::build_dom_xss_poc_url(
                    target.url.as_str(),
                    &vuln.source,
                    &payload,
                )
            } else {
                let base = crate::scanning::url_inject::effective_query_base(&target.url, param);
                crate::scanning::url_inject::build_injected_url(&base, param, &wire_payload)
            };
            // Graded from the flow's own shape, so the light-check and
            // self-bootstrap upgrades below can leave `result_type` at
            // `Verified` while the grade stays `Low`. See
            // `ast_integration::build_ast_dom_xss_result` for why that
            // disagreement is intentional during the tier migration.
            let (confidence, confidence_reason) =
                crate::scanning::ast_integration::grade_ast_finding(
                    &vuln.source,
                    &vuln.sink,
                    vuln.guarded,
                    self_bootstrap_verified,
                    posture,
                );
            let mut ast_result = crate::scanning::result::Result::builder(FindingType::AstDetected)
                .inject_type("DOM-XSS")
                .method(crate::scanning::url_inject::effective_method(
                    &target.method,
                    param,
                ))
                .confidence(confidence, confidence_reason)
                .data(result_url.clone())
                .param(param.name.clone())
                .payload(payload.clone())
                .evidence(format!(
                    "{}:{}:{} - {} (Source: {}, Sink: {}){}",
                    target.url.as_str(),
                    vuln.line,
                    vuln.column,
                    description,
                    vuln.source,
                    vuln.sink,
                    script_url
                        .as_ref()
                        .map(|(u, _)| format!(" [script: {u}]"))
                        .unwrap_or_default(),
                ))
                .cwe("CWE-79")
                .severity("Medium")
                .message_id(0)
                // The confirmation status is appended below, once the light
                // check has run — a finding this path promotes to `V` must not
                // also claim it "needs runtime confirmation" (#1238).
                .message_str(description.clone())
                .build();
            ast_result.set_injection_point(target, param);
            // A URL-surface source got its POC URL from
            // `build_dom_xss_poc_url`, which already placed the payload in the
            // fragment / query / path — synthesizing `?param=payload` on top
            // of that would emit a double-injection POC.
            ast_result.poc_url_complete = source_uses_url_surface;
            if !source_uses_url_surface {
                ast_result.request = Some(build_request_text(target, param, &payload));
                ast_result.wire_payload = (wire_payload != payload).then_some(wire_payload);
            }
            // Lightweight runtime verification (non-headless), once per
            // distinct payload and only up to the per-call cap / until cancel.
            if !verify_cache.contains_key(&payload) {
                let entry = if verify_cache.len() >= MAX_AST_LIGHT_VERIFY
                    || cancel.is_some_and(|c| c.load(std::sync::atomic::Ordering::Relaxed))
                {
                    (
                        false,
                        None,
                        Some("light check skipped: verification cap or scan cancelled".to_string()),
                    )
                } else {
                    let (v, resp, n) =
                        crate::scanning::light_verify::verify_dom_xss_light_with_client(
                            client, target, param, &payload,
                        )
                        .await;
                    let resp =
                        resp.map(|r| crate::scanning::result::bound_evidence_body(r, &payload));
                    (v, resp, n)
                };
                verify_cache.insert(payload.clone(), entry);
            }
            let (verified, rt_resp, note) = &verify_cache[&payload];
            let verified = *verified;
            if evidence_left > 0 {
                evidence_left -= 1;
                ast_result.response = Some(match rt_resp {
                    Some(b) => b.clone(),
                    None => crate::scanning::result::bound_evidence_body(
                        response_text.to_string(),
                        &payload,
                    ),
                });
            }
            if verified {
                ast_result.result_type = FindingType::Verified;
                ast_result.severity = "High".to_string();
                ast_result.message_str =
                    format!("{} [light check: confirmed]", ast_result.message_str);
            } else if self_bootstrap_verified {
                ast_result.result_type = FindingType::Verified;
                ast_result.severity = "High".to_string();
                ast_result.message_str = format!(
                    "{} [static self-bootstrap confirmed]",
                    ast_result.message_str
                );
            } else {
                ast_result.message_str = format!(
                    "{} (needs runtime confirmation) [light check: not confirmed]",
                    ast_result.message_str
                );
            }
            // Appended last so the CSP-style caveat trails the verdict instead
            // of splitting the description from it.
            if let Some(n) = note {
                ast_result.message_str = format!("{} [{}]", ast_result.message_str, n);
            }
            results.push(ast_result);
        }
    }
    results
}
/// Append a batch of findings to the shared results vector and bump the
/// running findings counter. No-op when `batch` is empty. The one
/// lock + extend + counter-update sequence for every finding source (libs,
/// initial AST, external JS, per-parameter workers, OOB callbacks) across the
/// CLI, server, and MCP surfaces.
///
/// The counter is bumped by [`count_new_matching_results`]: only findings that
/// match `limit_result_type` (already-uppercased `--limit-result-type`), so N
/// findings of a non-matching type cannot trip `--limit N`, and an AST finding
/// the report folds into one already counted is not counted again.
pub(crate) async fn accumulate_findings(
    results: &tokio::sync::Mutex<Vec<crate::scanning::result::Result>>,
    findings_count: &std::sync::atomic::AtomicUsize,
    batch: Vec<crate::scanning::result::Result>,
    args: &ScanArgs,
) {
    let mut batch = batch;
    if args.discard_below_min_confidence {
        batch.retain(|r| !args.below_min_confidence(r));
    }
    if batch.is_empty() {
        return;
    }
    let mut guard = results.lock().await;
    let added = count_new_matching_results(&guard, &batch, args);
    guard.extend(batch);
    // A stronger same-key winner can stop matching the report selection.
    if added >= 0 {
