                    j += 1;
                }
                if bytes.get(j) == Some(&b':') {
                    label_run += 1;
                    unary_run = 0;
                    if label_run > MAX_SOURCE_NESTING_DEPTH {
                        return true;
                    }
                    i = j + 1;
                    continue;
                }
                label_run = 0;
                if PREFIX_KEYWORDS.contains(&word) {
                    unary_run += 1;
                    if unary_run > MAX_SOURCE_NESTING_DEPTH {
                        return true;
                    }
                } else {
                    unary_run = 0;
                }
            }
            _ => {
                unary_run = 0;
                label_run = 0;
                i += 1;
            }
