        if !base_dir.exists() {
            return;
        }

        let all = load_all_mock_cases(&base_dir).expect("mock cases should load");
        for (handler_type, cases) in all {
            let mut ids = HashSet::new();
            for case in &cases {
                assert!(
                    ids.insert(case.id),
                    "Duplicate case id {} in handler type {}",
                    case.id,
                    handler_type
                );
            }
            assert!(
                !cases.is_empty(),
                "Handler type {} should include at least one case",
                handler_type
            );
        }
    }

